<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';import {useDispatchStore} from './stores/dispatch';import type{TrafficRequest,TrafficBlocker,WaitingPage,WaitingQuery}from './types';import{waitingTime,demoWaitingPage,sameWaitingMap,resourceView}from './waiting';import{shortTime}from './dashboard';
import {blockerOwners} from './traffic-display';
import TrafficBlockingDialog from './TrafficBlockingDialog.vue';
const selected=ref<TrafficRequest|null>(null);
const emit=defineEmits<{locate:[id:string];task:[id:string]}>(),store=useDispatchStore();
const panel=ref<HTMLElement>();
const resource=ref(''),priority=ref<number|string>(''),sort=ref<WaitingQuery['sort']>('LongestWait'),pageNumber=ref(1),result=ref<WaitingPage|null>(null),busy=ref(false),message=ref(''),appliedKey=ref('');let epoch=0,timer:ReturnType<typeof setInterval>|undefined;
const context=computed(()=>[store.demoMode,store.adapterIdentity?.sha256,store.snapshot?.map?.id,store.snapshot?.map?.version,store.snapshot?.map?.definitionHash].join('|'));
const queryKey=computed(()=>[resource.value,priority.value,sort.value,pageNumber.value].join('|'));
const current=computed(()=>{const age=store.now-Date.parse(result.value?.page.capturedAt??'');return appliedKey.value===queryKey.value&&store.fresh&&Number.isFinite(age)&&age>=-1000&&age<=7000;});
const resources=computed(()=>[...new Set([resource.value,...(result.value?.page.blockingResources??[])])].filter(Boolean));
function query():WaitingQuery{const p=priority.value===''?null:Number(priority.value);if(p!==null&&(!Number.isInteger(p)||p<0||p>100))throw new Error('最低优先级为0至100的整数');return{blockingResourceId:resource.value||null,minimumPriority:p,sort:sort.value,pageNumber:pageNumber.value,pageSize:25};}
async function load(){if(!store.fresh||busy.value)return;const mine=++epoch,ctx=context.value,requestedKey=queryKey.value;busy.value=true;message.value='';try{const q=query();const data=store.demoMode?demoWaitingPage(store.snapshot!,q):await store.api<WaitingPage>('/api/traffic/waiting',q);if(mine===epoch&&ctx===context.value){result.value=data;appliedKey.value=requestedKey;}}catch(e){if(mine===epoch){result.value=null;message.value=String(e);}}finally{if(mine===epoch)busy.value=false;}}
function reset(){selected.value=null;++epoch;busy.value=false;pageNumber.value=1;void load();}
watch([resource,priority,sort],reset);watch(context,()=>{resource.value='';result.value=null;appliedKey.value='';reset();});watch(()=>store.fresh,f=>{if(!f){selected.value=null;++epoch;busy.value=false;result.value=null;message.value='后台断连或观察过期，等待队列不可操作。';}else void load();});
watch(()=>store.snapshot,()=>{if(store.demoMode)void load();});
async function page(delta:number){pageNumber.value+=delta;await load();await nextTick();panel.value?.scrollIntoView({block:'start'});}
async function chainLocate(id:string){selected.value=null;await nextTick();emit('locate',id);}
async function chainTask(id:string){selected.value=null;await nextTick();emit('task',id);}
function canLocate(r:TrafficRequest,b:TrafficBlocker){const map=store.snapshot?.map;return current.value&&sameWaitingMap(result.value,map)&&r.blockingObservationCurrent&&r.mapId===map?.id&&r.mapVersionId===map?.version&&b.mapId===map?.id&&b.mapVersionId===map?.version&&!!resourceView(map,b.resourceId);}
onMounted(()=>{void load();timer=setInterval(()=>void load(),5000);});onUnmounted(()=>{++epoch;clearInterval(timer);});
</script>
<template><section ref="panel" class="waiting-panel control-panel"><header class="section-heading"><h2>交通等待队列 <small>{{store.demoMode?'浏览器合成示例':'后台完整队列分页'}}</small></h2><button :disabled="busy||!store.fresh" @click="load">刷新等待队列</button></header>
<div class="waiting-filters"><label>阻塞资源<select v-model="resource" aria-label="等待队列阻塞资源"><option value="">全部资源</option><option v-for="id in resources" :key="id" :value="id">{{id}}</option></select></label><label>最低优先级<input v-model="priority" aria-label="等待队列最低优先级" type="number" min="0" max="100" placeholder="全部"/></label><label>排序<select v-model="sort" aria-label="等待队列排序"><option value="LongestWait">等待最长优先</option><option value="PriorityThenWait">任务优先级优先</option></select></label></div>
<p v-if="message" role="status">{{message}}</p><template v-if="result"><p class="waiting-summary">等待总数 {{result.page.totalWaiting}} · 筛选命中 {{result.page.totalMatched}} · 第{{result.page.pageNumber}}页 · 观察 {{shortTime(result.page.capturedAt)}} · {{current?'有效观察':'旧观察或筛选待刷新，不可定位'}}</p>
<details v-if="result.page.cycleRisks?.length" class="cycle-risks"><summary>资源依赖循环风险 · {{result.page.cycleRisks.length}} 组{{current?'':'（旧观察）'}}</summary><p>分析覆盖本次后台完整等待快照，不随当前筛选和分页缩小。这是资源依赖风险，不等于物理死锁，不会自动解锁、倒车或释放占用。</p><article v-for="risk in result.page.cycleRisks" :key="risk.cycleId"><b>{{risk.vehicleIds.join(' → ')}}</b><p>{{risk.message}}</p><p>资源：{{risk.resourceIds.join('、')}}</p><div class="cycle-tasks"><button v-for="id in risk.taskIds" :key="id" :disabled="!current" @click="emit('task',id)">查看任务 {{id}}</button></div><details><summary>查看等待与持有关系（{{risk.links.length}} 条）</summary><p v-for="link in risk.links" :key="JSON.stringify(link)">{{link.waitingVehicleId}} / {{link.waitingTaskId}} 等待 {{link.resourceId}} → {{link.holdingVehicleId}} / {{link.holdingTaskId}} 持有{{link.heartbeatExpired?'（持有心跳过期，占用仍保留）':''}}；地图 {{link.mapId||'未知'}} / {{link.mapVersionId||'未知'}}</p></details></article></details>
<p v-if="result.page.cycleAnalysisMessage" class="panel-footnote">{{result.page.cycleAnalysisMessage}}</p>
<div class="waiting-table"><table class="dialog-table"><thead><tr><th>任务 / 车辆</th><th>优先级</th><th>等待时长（本次观察）</th><th>阻塞资源 / 车辆</th><th>地图 / 版本</th><th>原因</th></tr></thead><tbody><tr v-for="r in result.page.items" :key="r.stepId"><td><button :disabled="!current" @click="emit('task',r.taskId)">{{r.taskId}}</button><button :disabled="!current" @click="selected=r">阻塞链</button><small>{{r.vehicleId}} · {{r.stepId}}</small></td><td>{{r.priority??'未知'}}</td><td>{{waitingTime(r)}}<small>{{r.waitingAlertLevel==='Critical'?'严重等待':r.waitingAlertLevel==='Warning'?'等待超阈值':''}}</small></td><td><div v-for="b in blockerOwners(r.blockers)" :key="JSON.stringify([b.resourceId,b.mapId,b.mapVersionId,b.taskId,b.vehicleId])"><button :disabled="!b.records.every(record=>canLocate(r,record))" @click="emit('locate',b.resourceId)">定位 {{b.resourceId}}</button><small>{{b.vehicleId}} · {{b.stepIds.length}}个占用步骤 · {{b.heartbeatExpired?'心跳过期，占用仍保留':'占用保留'}}</small><details><summary>原占用任务／步骤</summary><small>{{b.taskId}}</small><small v-for="id in b.stepIds" :key="id">{{id}}</small></details></div><small v-if="!r.blockingObservationCurrent">阻塞观察待复核</small><small v-if="r.blockers.some(b=>!canLocate(r,b))">异图、边界缺失或观察无效：不能定位</small></td><td>{{r.mapId||'未提供'}}<small>{{r.mapVersionId||'未提供'}}</small></td><td><strong>{{r.waitingCategory==='Equipment'?'倒料设备许可等待':'路权／候车位等待'}}</strong><div>{{r.reason}}</div></td></tr></tbody></table></div><p v-if="!result.page.items.length" class="empty-panel">当前筛选没有等待记录。</p>
<div class="waiting-pages"><button :disabled="busy||!current||result.page.pageNumber<=1" @click="page(-1)">上一页等待</button><button :disabled="busy||!current||result.page.pageNumber*result.page.pageSize>=result.page.totalMatched" @click="page(1)">下一页等待</button></div></template>
<p class="panel-footnote">只读查询不改变调度优先级或路权。每5秒刷新，时长使用后台观察，不从任务创建时间推算；未知起点不当零秒。跨图记录可查看，不能定位到当前图。</p><TrafficBlockingDialog v-if="selected" :request="selected" @close="selected=null" @locate="chainLocate" @task="chainTask"/></section></template>
<style scoped>.waiting-panel{margin-top:18px;padding-bottom:14px}.waiting-filters{display:flex;gap:18px;flex-wrap:wrap;padding:12px 16px;font-size:12px}.waiting-filters label{display:flex;align-items:center;gap:8px}.waiting-filters input{width:100px}.waiting-panel>p,.waiting-pages{padding:0 16px;font-size:12px;line-height:1.8}.cycle-risks{margin:12px 16px;padding:12px;border:1px solid #a27a37;border-radius:6px;font-size:12px;line-height:1.8;overflow-wrap:anywhere}.cycle-risks>summary{cursor:pointer;color:#edc575;font-weight:600}.cycle-risks article{border-top:1px solid #665033;padding-top:10px;margin-top:10px}.cycle-tasks{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:8px}.waiting-table{overflow:auto;height:460px;padding:0 16px}.waiting-table th{position:sticky;top:0;background:#152240;z-index:1}.waiting-table table{min-width:850px}.waiting-table td{max-width:300px;overflow-wrap:anywhere}.waiting-table small{display:block;color:#9ab3cc;line-height:1.8}.waiting-pages button{margin:8px}.waiting-summary{color:#98c8de}</style>
